// The reading of an MCP tool call that writes to a repository, from the structure of the tool name and the input.
// The tool name is `mcp__<server>__<tool>`, and the verb is one word of the tool part.

import type { Repo } from "./remote.ts";

/** The words of a tool name that mean a write. */
const WRITE_VERBS: ReadonlySet<string> = new Set([
  "create",
  "update",
  "add",
  "merge",
  "push",
  "delete",
  "edit",
  "write",
  "comment",
  "fork",
  "close",
  "reopen",
  "submit",
  "assign",
  "request",
  "remove",
  "set",
  "post",
  "upload",
  "commit",
  "publish",
  "dismiss",
  "transfer",
  "lock",
  "resolve",
]);

/** The lower-case words of a name that uses `_`, `-`, or camel case. */
const wordsOf = (name: string): string[] =>
  name
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .toLowerCase()
    .split(/[_-]+/)
    .filter((w) => w !== "");

/** What a write by an MCP tool targets: the repository its input names, or the folder of the session. */
export type McpTarget = { repo: Repo } | "session";

/**
 * The target of the MCP call `tool` with `input`, or `undefined` when the call is not a repository write.
 * A write verb in the tool part is needed.
 * The input fields `owner` and `repo` name the repository, as the GitHub servers take them.
 * Without them, only a server whose name has the word `github` targets the repository of the session.
 */
export const mcpTargetOf = (
  tool: string,
  input: Readonly<Record<string, unknown>>,
): McpTarget | undefined => {
  if (!tool.startsWith("mcp__")) return undefined;
  const [, server = "", ...rest] = tool.split("__");
  if (!wordsOf(rest.join("__")).some((w) => WRITE_VERBS.has(w)))
    return undefined;
  const { owner, repo } = input;
  if (typeof owner === "string" && typeof repo === "string" && owner && repo)
    return { repo: { host: "github.com", owner, name: repo } };
  return wordsOf(server).includes("github") ? "session" : undefined;
};
